const $=id=>document.getElementById(id),categories={arcane:'마법',explosions:'폭발',fire:'불',holy:'신성·보호',ice:'얼음',impacts:'타격',lightning:'번개',melee:'근접 공격',nature:'자연',projectiles:'발사체',shadow:'그림자',smoke:'연기·먼지',status:'상태 효과',ui:'획득·레벨업',water:'물',wind:'바람'};
let entries=[],paused=matchMedia('(prefers-reduced-motion: reduce)').matches,time=0,last=performance.now(),selected=null;const images=new Map(),visible=new Set();
$('pause').textContent=paused?'전체 재생':'전체 일시정지';
function load(e){if(images.has(e.key))return;const image=new Image();images.set(e.key,{image,ready:false});image.onload=()=>{images.get(e.key).ready=true;};image.onerror=()=>{images.get(e.key).error=true;};image.src=e.file;}
function draw(canvas,e){const c=canvas.getContext('2d'),a=images.get(e.key);c.clearRect(0,0,canvas.width,canvas.height);if(!a?.ready){c.fillStyle='#cad8df';c.font='14px system-ui';c.textAlign='center';c.fillText(a?.error?'불러오지 못했습니다. 새로고침해 주세요.':'불러오는 중',canvas.width/2,canvas.height/2);return;}
 const cycle=e.frames*e.frame_ms/1000,phase=time%(cycle+(e.loop?0:.45)),frame=Math.min(e.frames-1,Math.floor(phase*1000/e.frame_ms)),[w,h]=e.size,scale=Math.min(canvas.width*.85/w,canvas.height*.85/h,canvas.width>400?5:3),dx=(canvas.width-w*scale)/2,dy=(canvas.height-h*scale)/2;c.imageSmoothingEnabled=false;c.drawImage(a.image,(frame%8)*w,Math.floor(frame/8)*h,w,h,dx,dy,w*scale,h*scale);}
const observer=new IntersectionObserver(changes=>{for(const item of changes){const n=Number(item.target.dataset.number);if(item.isIntersecting){visible.add(n);load(entries[n-1]);}else visible.delete(n);}},{rootMargin:'120px'});
function open(e){selected=e;load(e);$('detailTitle').textContent='#'+String(e.number).padStart(3,'0')+' '+e.name;$('detailText').textContent=e.original+' · '+e.size.join(' × ')+'px · '+e.frames+'프레임';$('detail').showModal();}
function filter(){const q=$('search').value.trim().replace(/^#/,'').toLowerCase(),category=$('category').value;let count=0;for(const e of entries){const card=document.getElementById(String(e.number)),match=(!category||category===e.category)&&(!q||String(e.number)===String(Number(q))||e.name.toLowerCase().includes(q)||e.original.toLowerCase().includes(q));card.hidden=!match;if(match)count++;}$('count').textContent=count+' / 101개';}
function hash(){const e=entries[Number(location.hash.slice(1))-1];if(e){$('search').value='';$('category').value='';filter();const card=document.getElementById(String(e.number));card.scrollIntoView({block:'center'});load(e);}}
try{const response=await fetch('materials.json?v=studio1');if(!response.ok)throw Error('catalog');entries=await response.json();$('category').insertAdjacentHTML('beforeend',Object.entries(categories).map(([id,name])=>`<option value="${id}">${name}</option>`).join(''));
 $('grid').innerHTML=entries.map(e=>`<article class="card" id="${e.number}" data-number="${e.number}"><canvas width="320" height="200" aria-label="${e.number}번 ${e.name} 원본 애니메이션"></canvas><div class="info"><h2><span class="number">#${String(e.number).padStart(3,'0')}</span>${e.name}</h2><small>${e.original} · ${categories[e.category]}</small><button data-open="${e.number}">${e.number}번 크게 보기</button></div></article>`).join('');document.querySelectorAll('.card').forEach(card=>observer.observe(card));filter();hash();
}catch{$('count').textContent='소재 목록을 불러오지 못했습니다. 새로고침해 주세요.';}
$('grid').onclick=event=>{const button=event.target.closest('[data-open]');if(button)open(entries[Number(button.dataset.open)-1]);};$('close').onclick=()=>$('detail').close();$('detail').onclose=()=>{selected=null;};$('search').oninput=filter;$('category').onchange=filter;window.addEventListener('hashchange',hash);$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'전체 재생':'전체 일시정지';};
function animate(now){if(!paused&&!document.hidden)time+=Math.min(.1,(now-last)/1000);last=now;for(const n of visible){const card=document.getElementById(String(n));if(!card.hidden)draw(card.querySelector('canvas'),entries[n-1]);}if(selected)draw($('detail').querySelector('canvas'),selected);requestAnimationFrame(animate);}requestAnimationFrame(animate);
